void Labels::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Post("/ad_accounts/{ad_account_id}/labels/{label_id}/apply", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdlabelslabelIdapplyPostRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/labels", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdlabelsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/labels", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdlabelsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/labels/{label_id}/remove", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdlabelslabelIdremovePostRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/labels", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdlabelsPatchRequest(req, res, auth);
    });
}

